content:
RawPacket* newPacket = new RawPacket();
                bool packetRead = getNextPacket(*newPacket);
                if (packetRead)
                {
                        packetVec.pushBack(newPacket);
                }
                else
                {
                        delete newPacket;
                        break;
                }
        }

        return numOfPacketsRead;
}


